//! Generates decoder tables from Arm's open-source machine-readable architecture specification (AARCHMRS,
//! BSD-3-Clause): https://developer.arm.com/Architectures/A-Profile%20Architecture
//!
//! Usage: armgen <AARCHMRS directory> <A64|A32|T16|T32> <output file>
//!
//! The generated file holds every encoding of the instruction set (bit pattern, decode conditions, fields,
//! assembly syntax and aliases) and a decision tree over them; for A64 also the system register and system
//! operation names. T16 and T32 are the 16-bit and 32-bit halves of the T32 instruction set, which the
//! specification models as one set of 32-bit words with the first halfword in bits 31..16; 16-bit encodings
//! use bits 15..0.

mod conditions;
mod registers;
mod syntax;
mod tree;

use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::PathBuf;

use anyhow::{Context, Result, bail};
use serde_json::Value;

use crate::conditions::Conditions;

#[derive(Clone, Debug)]
pub struct Field {
    pub name: String,
    pub start: u32,
    pub width: u32,
}

pub type Scope = BTreeMap<String, Field>;

pub struct Encoding {
    pub name: String,
    pub mask: u32,
    pub value: u32,
    pub condition: usize,
    pub fields: Vec<Field>,
    pub syntax: String,
    pub aliases: Vec<String>,
}

fn main() -> Result<()> {
    // The specification's ASTs nest deeply; parse and walk them on a thread with room to recurse.
    std::thread::Builder::new().stack_size(512 << 20).spawn(run)?.join().expect("generator thread panicked")
}

fn run() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let [_, input, set_name, output] = args.as_slice() else {
        bail!("usage: armgen <AARCHMRS directory> <A64|A32|T16|T32> <output file>");
    };
    let input = PathBuf::from(input);
    let instructions = read_json(&input.join("Instructions.json"))?;
    let registers = read_json(&input.join("Registers.json"))?;

    let meta = &instructions["_meta"];
    let version = format!(
        "{} (architecture {}, build {})",
        str_of(&meta["version"]["ref"]),
        str_of(&meta["version"]["architecture"]),
        str_of(&meta["version"]["build"])
    );
    let copyright = str_of(&meta["license"]["copyright"]).to_owned();

    let (spec_set, width) = match set_name.as_str() {
        "A64" | "A32" => (set_name.as_str(), None),
        "T16" => ("T32", Some(16)),
        "T32" => ("T32", Some(32)),
        other => bail!("unknown instruction set {other}"),
    };
    let mut set = instructions["instructions"]
        .as_array()
        .context("instructions")?
        .iter()
        .find(|set| set["name"] == spec_set)
        .with_context(|| format!("no {spec_set} instruction set"))?
        .clone();
    // Keep the groups of one encoding width.
    if let Some(width) = width
        && let Some(children) = set["children"].as_array_mut()
    {
        children.retain(|child| child["encoding"]["width"].as_u64() == Some(width));
    }

    let mut generator = Generator {
        rules: instructions["assembly_rules"].as_object().context("assembly_rules")?,
        conditions: Conditions::default(),
        encodings: Vec::new(),
    };
    generator.walk(&set, &Scope::new(), &[], 0, 0)?;

    let tree = tree::build(&generator.encodings);
    let registers = (set_name == "A64").then(|| registers::collect(&registers)).transpose()?;

    let mut out = String::new();
    writeln!(out, "// @generated by tools/armgen ({set_name}) from Arm AARCHMRS {version}. Do not edit.")?;
    writeln!(out, "// Derived from data {copyright}")?;
    writeln!(out, "// Licensed under the BSD 3-clause license; see LICENSE-ARM in this directory.")?;
    writeln!(out)?;
    writeln!(out, "use super::spec_types::*;")?;
    writeln!(out)?;
    // Encodings share field lists and syntaxes; emit each distinct one once as a const.
    let mut shared = Interner::default();
    let mut rows = Vec::new();
    for encoding in &generator.encodings {
        let fields: Vec<String> =
            encoding.fields.iter().map(|f| format!("f({:?}, {}, {})", f.name, f.start, f.width)).collect();
        let fields = shared.intern("FIELDS", "&[Field]", format!("&[{}]", fields.join(", ")));
        let syntax = shared.intern("SYNTAX", "Syntax", encoding.syntax.clone());
        let aliases = shared.intern("ALIASES", "&[Alias]", format!("&[{}]", encoding.aliases.join(", ")));
        rows.push(format!(
            "    enc({:?}, {:#010x}, {:#010x}, {}, {fields}, {syntax}, {aliases}),",
            encoding.name, encoding.mask, encoding.value, encoding.condition
        ));
    }
    out.push_str(&shared.definitions);
    writeln!(out)?;
    writeln!(out, "pub static ENCODINGS: [Encoding; {}] = [", generator.encodings.len())?;
    for row in rows {
        writeln!(out, "{row}")?;
    }
    writeln!(out, "];")?;
    writeln!(out)?;
    tree.emit(&mut out)?;
    writeln!(out)?;
    writeln!(
        out,
        "pub static TABLES: Tables = Tables {{ encodings: &ENCODINGS, nodes: &NODES, candidates: &CANDIDATES, \
         condition, specific_aliases_last: {} }};",
        set_name == "A64"
    )?;
    writeln!(out)?;
    generator.conditions.emit(&mut out)?;
    writeln!(out)?;
    if let Some(registers) = &registers {
        registers.emit(&mut out)?;
    }

    std::fs::write(output, out).with_context(|| format!("writing {output}"))?;
    eprintln!(
        "armgen: {set_name}: {} encodings, {} conditions, {} tree nodes",
        generator.encodings.len(),
        generator.conditions.len(),
        tree.nodes.len()
    );
    Ok(())
}

/// Emits each distinct constant expression once, under a numbered name.
#[derive(Default)]
struct Interner {
    names: std::collections::HashMap<String, String>,
    definitions: String,
}

impl Interner {
    fn intern(&mut self, prefix: &str, ty: &str, code: String) -> String {
        if let Some(name) = self.names.get(&code) {
            return name.clone();
        }
        let name = format!("{prefix}_{}", self.names.len());
        self.definitions.push_str(&format!("const {name}: {ty} = {code};\n"));
        self.names.insert(code, name.clone());
        name
    }
}

fn read_json(path: &std::path::Path) -> Result<Value> {
    let text = std::fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    Ok(serde_json::from_slice(&text)?)
}

pub fn str_of(value: &Value) -> &str {
    value.as_str().unwrap_or("")
}

/// Strips the quotes from a bit-pattern value such as `'01x'`.
pub fn pattern_of(value: &Value) -> Result<String> {
    let text = value["value"].as_str().context("pattern value")?;
    Ok(text.trim_matches('\'').to_owned())
}

struct Generator<'a> {
    rules: &'a serde_json::Map<String, Value>,
    conditions: Conditions,
    encodings: Vec<Encoding>,
}

impl Generator<'_> {
    /// Walks the instruction tree, accumulating the bit pattern, field scope and decode conditions of each
    /// group down to the instructions at its leaves.
    fn walk(&mut self, node: &Value, scope: &Scope, conditions: &[String], mask: u32, value: u32) -> Result<()> {
        let mut scope = scope.clone();
        let (mut mask, mut value) = (mask, value);
        let mut own_fields = Vec::new();
        if let Some(values) = node["encoding"]["values"].as_array() {
            for item in values {
                let start = item["range"]["start"].as_u64().context("range start")? as u32;
                let width = item["range"]["width"].as_u64().context("range width")? as u32;
                let pattern = pattern_of(&item["value"])?;
                if pattern.len() != width as usize {
                    bail!("pattern {pattern:?} does not match width {width} in {}", node["name"]);
                }
                for (i, bit) in pattern.chars().enumerate() {
                    let position = start + width - 1 - i as u32;
                    match bit {
                        '0' => mask |= 1 << position,
                        '1' => {
                            mask |= 1 << position;
                            value |= 1 << position;
                        }
                        'x' => {}
                        other => bail!("unexpected pattern bit {other:?}"),
                    }
                }
                if item["_type"] == "Instruction.Encodeset.Field" {
                    let field = Field { name: str_of(&item["name"]).to_owned(), start, width };
                    own_fields.push(field.clone());
                    scope.insert(field.name.clone(), field);
                }
            }
        }

        let mut conditions = conditions.to_vec();
        if let Some(code) = self.conditions.compile_decode(&node["condition"], &scope)? {
            conditions.push(code);
        }

        match str_of(&node["_type"]) {
            "Instruction.Instruction" => self.instruction(node, &scope, &conditions, mask, value),
            "Instruction.InstructionSet" | "Instruction.InstructionGroup" => {
                for child in node["children"].as_array().into_iter().flatten() {
                    self.walk(child, &scope, &conditions, mask, value)?;
                }
                Ok(())
            }
            other => bail!("unexpected node type {other}"),
        }
    }

    fn instruction(&mut self, node: &Value, scope: &Scope, conditions: &[String], mask: u32, value: u32) -> Result<()> {
        // Every field in scope, ordered from the most significant bit, so operands can index them.
        let mut fields: Vec<Field> = scope.values().cloned().collect();
        fields.sort_by(|a, b| b.start.cmp(&a.start).then(a.name.cmp(&b.name)));

        let condition = self.conditions.intern(conditions);
        let syntax = syntax::emit(self.rules, node, &fields)?;
        let mut aliases = Vec::new();
        for child in node["children"].as_array().into_iter().flatten() {
            if child["_type"] != "Instruction.InstructionAlias" {
                bail!("unexpected child {} of {}", child["_type"], node["name"]);
            }
            let condition = match self.conditions.compile_decode(&child["condition"], scope)? {
                Some(code) => self.conditions.intern(&[code]),
                None => 0,
            };
            let preferred = match self.conditions.compile_decode(&child["preferred"], scope)? {
                Some(code) => self.conditions.intern(&[code]),
                None => 0,
            };
            aliases.push(format!(
                "alias({:?}, {condition}, {preferred}, {})",
                str_of(&child["operation_id"]),
                syntax::emit(self.rules, child, &fields)?
            ));
        }

        self.encodings.push(Encoding {
            name: str_of(&node["name"]).to_owned(),
            mask,
            value,
            condition,
            fields,
            syntax,
            aliases,
        });
        Ok(())
    }
}
